window.OmniAddonControls=Object.freeze({attach(root){let prior=document.activeElement;const restore=()=>{let target=prior?.isConnected&&!root.contains(prior)?prior:document.querySelector('video,article,main')||document.body;if(root.contains(target))target=document.body;const old=target.getAttribute('tabindex');target.setAttribute('tabindex','-1');target.focus({preventScroll:true});if(old===null)target.removeAttribute('tabindex');else target.setAttribute('tabindex',old)};root.addEventListener('focusin',e=>{if(e.relatedTarget&&!root.contains(e.relatedTarget))prior=e.relatedTarget});root.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();const current=document.activeElement;if(current.tagName==='SELECT'&&['ArrowLeft','ArrowRight'].includes(e.key)){current.selectedIndex=Math.max(0,Math.min(current.options.length-1,current.selectedIndex+(e.key==='ArrowRight'?1:-1)));current.dispatchEvent(new Event('change'));return}const items=[...root.querySelectorAll('button,select,a[href]')].filter(x=>!x.disabled&&x.getClientRects().length);if(!items.includes(current)){items[0]?.focus();return}const r=current.getBoundingClientRect(),horizontal=['ArrowLeft','ArrowRight'].includes(e.key),sign=['ArrowLeft','ArrowUp'].includes(e.key)?-1:1;const next=items.filter(x=>x!==current).map(element=>{const b=element.getBoundingClientRect(),dx=b.x+b.width/2-r.x-r.width/2,dy=b.y+b.height/2-r.y-r.height/2;return{element,along:(horizontal?dx:dy)*sign,off:Math.abs(horizontal?dy:dx)}}).filter(x=>x.along>2).sort((a,b)=>a.along+2*a.off-b.along-2*b.off)[0];next?.element.focus();return}if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();restore()}},true);root.omniRestoreFocus=restore;return restore}});
